CREATE TABLE IF NOT EXISTS kb_articles (
  id text PRIMARY KEY,
  persona text NOT NULL,
  kind text NOT NULL,
  title text NOT NULL,
  mins int NOT NULL DEFAULT 0,
  updated text,
  view text,
  roles text[] NOT NULL DEFAULT '{}',
  tags text[] NOT NULL DEFAULT '{}',
  summary text NOT NULL DEFAULT '',
  body jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'published',
  sort_order int NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_kb_articles_persona ON kb_articles(persona, status);

CREATE TABLE IF NOT EXISTS kb_tours (
  id text PRIMARY KEY,
  persona text NOT NULL,
  title text NOT NULL,
  mins int NOT NULL DEFAULT 0,
  why text NOT NULL DEFAULT '',
  stops jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'held',
  sort_order int NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_kb_tours_persona ON kb_tours(persona, status);

ALTER TABLE kb_articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE kb_tours    ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['kb_articles','kb_tours'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS "anon_all_%1$s" ON %1$I', t);
    EXECUTE format('CREATE POLICY "anon_all_%1$s" ON %1$I FOR ALL TO anon, authenticated USING (true) WITH CHECK (true)', t);
  END LOOP;
END $$;

INSERT INTO kb_articles (id, persona, kind, title, mins, updated, view, roles, tags, summary, body, status, sort_order) VALUES
('KB-O01', 'operator', 'start', 'What this console is for', 3, '18 Jul 2026', 'op-dashboard', '{}', '{"overview"}', 'The operator runs the marketplace: who may sell, what may be listed, what it costs to sell, and who gets paid.', '[["The four jobs","Supply — deciding who sells and what they may list. Commercials — commission, promotions, tax and settlement. Operations — orders, inventory, numbers and support. Governance — access, audit and the rules themselves."],["What the operator does not do","You do not price a seller’s product for them, and you do not fulfil their orders. The marketplace sets the floor and the rules; the seller sets the price inside them."],["Where the numbers come from","Every figure on the overview reconciles to the order register. Gross value equals the sum of the categories and the sum of order gross. If a number here disagrees with a statement, the statement is right and this is a bug worth raising."]]'::jsonb, 'published', 0),
('KB-O02', 'operator', 'howto', 'Onboard a seller through the seven gates', 5, '21 Jul 2026', 'op-onboarding', '{"OR-ADMIN","OR-ONB"}', '{"partners","onboarding","kyc"}', 'Invite, verify, and clear a seller to trade — and what to do when a gate fails.', '[["Before you start","Have the seller’s legal entity name and the email of the person who can sign. An invitation names a recipient; it is not a generic link."],["The gates","Application, KYC and beneficial ownership, sanctions screening, commercial terms, technical readiness, catalogue readiness, go-live. Each has an owner and a target in working days."],["Clearing a gate","Open the application and the gate. Every submission the seller made is kept in full, so you are deciding on the evidence rather than on a summary."],["When a gate fails","Failing KYC stops the application. It is not a rejection of the company — they may reapply with corrected documentation. Say which document and why, because \"failed KYC\" tells them nothing they can act on."],["Dual control","Some gates require a second approver. That is set in the gate policy, not per application, so it cannot be waived case by case."]]'::jsonb, 'published', 1),
('KB-O03', 'operator', 'howto', 'Review a listing and decide it', 4, '19 Jul 2026', 'op-catalogue', '{"OR-ADMIN","OR-CAT"}', '{"catalogue","review"}', 'What the queue is checking, and how to reject in a way the seller can act on.', '[["What is automatic and what is not","Automated rules are already evaluated when a listing reaches you. Your job is the ones a machine cannot judge."],["Reading the checklist","A rule set to enforce has already blocked publication. A rule set to warn is on your list but did not block — you decide."],["Rejecting well","Name the rule, name the evidence that is missing, and say what would clear it. A rejection the seller cannot act on comes straight back as a support ticket."],["Asking rather than rejecting","If it is a question rather than a failure, use Ask the partner. It keeps the listing in the queue instead of restarting the clock."]]'::jsonb, 'published', 2),
('KB-O04', 'operator', 'policy', 'How listing rules work', 4, '26 Jul 2026', NULL, '{"OR-ADMIN","OR-CAT"}', '{"rules","policy"}', 'Rules are authored once and applied per category at three levels.', '[["Three levels","Enforce blocks publication. Warn appears on the reviewer’s checklist but does not block. Off removes the check entirely, which is a decision worth being deliberate about."],["Author once, apply many times","A rule carries what it requires, how it is checked, who owns it and what evidence it needs. The matrix then decides where it applies."],["What a rule costs","An automated rule costs nothing per listing. A manual one costs about nine reviewer minutes on every listing it touches — on a four-hundred-listing category that is sixty hours a pass. The editor states the figure before you save."],["Locked rules","Sanctions screening is fixed at enforce everywhere. It is not a marketplace policy choice."],["Retiring","Retire rather than delete. Past decisions cite the rule, and retiring it is not an amnesty — listings already rejected under it stay rejected."]]'::jsonb, 'held', 3),
('KB-O05', 'operator', 'concept', 'Commission, commercial models and the cost floor', 5, '20 Jul 2026', NULL, '{"OR-ADMIN","OR-FIN"}', '{"commercial","pricing"}', 'Seven models, and the one limit none of them may cross.', '[["Model first, parameters second","Changing the commercial model changes which parameters apply. A revenue-share plan and a fixed-fee plan do not share a rate field."],["The cost floor","No discount, promotion, bundle or override may take a line below cost. The clamp is in the pricing engine, not in rule authoring, so it cannot be written around."],["Who funds a discount","Each seller sets how much of their margin the marketplace may spend. Beyond that, the discount is marketplace-funded and attributed as such."],["Reading a margin stack","Sale, less commission, less payment and per-order fees, equals settled. Less cost equals margin. Where fees exceed margin, that is flagged rather than shown as a healthy settlement."]]'::jsonb, 'held', 4),
('KB-O06', 'operator', 'howto', 'Approve a settlement run', 4, '22 Jul 2026', 'op-settlement', '{"OR-ADMIN","OR-FIN"}', '{"settlement","money"}', 'What to check before you release money, and why it asks twice.', '[["Read the statement, not the total","Open a statement before approving. It reconciles to order lines; the total on its own tells you nothing about whether it is right."],["What is deducted","Commission, payment fees, per-order fees, withholding tax and refunds. Each is a line, not a lump."],["Second check","Approval asks you to re-authenticate. An unattended screen that is already signed in should not be able to release a payment run."],["After approval","It is the point of no return in this flow. A correction after approval is an adjustment on the next run, not an edit to this one."]]'::jsonb, 'published', 5),
('KB-O07', 'operator', 'concept', 'Numbers and SIMs come from the BSS', 4, '26 Jul 2026', NULL, '{"OR-ADMIN","OR-SUP"}', '{"inventory","sim","bss"}', 'ICCID, IMSI and MSISDN are not held here. This screen queries the Number Management system.', '[["Who owns what","The operator’s Number Management and Logical Inventory systems own the resources. The marketplace holds a reservation and an assignment reference against an order."],["Why not both","A second register of numbers guarantees two answers to the same question, and the wrong one will be the one somebody quotes to a customer."],["Reconciliation","Runs nightly. Where we disagree with the BSS, we are corrected. Nothing here writes to the BSS — not a screen, not a bulk file."],["eSIM states","Released, downloaded, installed, enabled, disabled, deleted. These are the SGP.22 states; the SM-DP+ owns them and we observe them. Assignment creates a profile in released — it is not installed until the device fetches it."]]'::jsonb, 'held', 6),
('KB-O08', 'operator', 'fix', 'A message did not arrive', 3, '26 Jul 2026', NULL, '{"OR-ADMIN","OR-SUP"}', '{"notifications","support"}', 'How to answer "I never got the message" from one screen.', '[["Find it","Message delivery, then search the recipient. Every send carries its provider, attempts, reason code and cost."],["Read the state","Delivered means the carrier confirmed handset receipt. Sent means the provider passed it on and nothing has come back yet. No receipt means the channel cannot tell us — push, for example, confirms acceptance, not display."],["Hard versus soft","An invalid number, an opt-out, a carrier block or an unapproved template will never succeed. Retrying produces another charge and no message. Fix the underlying record instead."],["Soft failures","Handset off or a provider limit reached will retry with backoff and fail over to the standby provider after two attempts."]]'::jsonb, 'held', 7),
('KB-O09', 'operator', 'policy', 'Who can read the audit log', 3, '24 Jul 2026', 'op-audit', '{"OR-ADMIN"}', '{"governance","audit"}', 'Read scope is by role, and it is deliberately narrow.', '[["No edit path","There is no way to change or delete an entry, for anyone. A log that can be edited is not evidence."],["Scoped, not open","A support agent seeing a settlement approval, or one seller seeing another’s onboarding, would be a data breach dressed up as transparency."],["Redaction","Personal data is redacted rather than the entry hidden — the reader should still know an event occurred. Your own actions are never redacted from you."],["Integrity","Entries are hash-chained and anchored daily to object-locked storage. Verification can be run on demand, and the run is itself recorded."]]'::jsonb, 'published', 8),
('KB-O10', 'operator', 'howto', 'Change many records at once', 4, '26 Jul 2026', NULL, '{"OR-ADMIN","OR-CAT","OR-FIN"}', '{"bulk","efficiency"}', 'A file for different values, a common update for the same value.', '[["Which door","If every record gets the same value, use a common update. If each needs a different one, use a file. A common update pretending to be a spreadsheet is how the wrong price reaches a whole category."],["Always a dry run","Nothing is written until you have seen, row by row, what would change. Download the template — it comes pre-filled with current values, so an edit is a diff rather than a retype."],["Rejections","A bad row is rejected on its own and the rest still apply. A file failing more than a fifth of its rows is refused outright: that is a wrong file, not a set of typos."],["What bulk cannot do","It updates. It never creates and never deletes. It cannot price below cost, and it cannot change your own role or status."]]'::jsonb, 'held', 9),
('KB-P01', 'partner', 'start', 'Selling here: the short version', 3, '18 Jul 2026', 'pt-dashboard', '{}', '{"overview"}', 'Listing is free. You pay commission only when something sells.', '[["The deal","No listing fee and no shelf rent. Commission applies on a sale, at the rate in your settlement plan."],["What you control","Your price above the floor, your stock, your fulfilment, your media, and your own console’s branding."],["What the marketplace controls","Which categories you may sell in, the rules every listing is checked against, the checkout, and the settlement documents."],["Getting paid","On your billing cycle, less commission, fees, withholding and refunds. Every deduction is itemised on the statement."]]'::jsonb, 'published', 0),
('KB-P02', 'partner', 'howto', 'Create a listing that passes review first time', 5, '25 Jul 2026', 'pt-newlisting', '{"PR-OWNER","PR-CAT"}', '{"catalogue","listing"}', 'The six steps, and the three things that cause most rejections.', '[["Media is not optional","A minimum number of images, one marked primary, and alt text on every item. Submission is blocked until all three are satisfied — a listing nobody can read is a listing some buyers cannot buy."],["Three prices","Cost is what it costs you. List is the reference price. Sale is what a buyer pays today. Cost is never shown to a buyer, and a sale price at or below cost is refused."],["Declarations","Sign all four before submitting. Unsigned declarations do not block submission, but the review will come back to you for them, which costs you a day."],["Fulfilment","Point it at an endpoint. Left on manual, every order waits for a human to open the portal."],["The category cap","Each category limits how many live listings one seller may hold. The wizard shows your remaining headroom when you choose the category."]]'::jsonb, 'published', 1),
('KB-P03', 'partner', 'concept', 'What you actually get paid', 4, '22 Jul 2026', 'pt-settlement', '{"PR-OWNER","PR-FIN"}', '{"settlement","money"}', 'From sale price to bank credit, itemised.', '[["The chain","Sale price, less commission, less payment fees, less per-order fees, less withholding tax, less refunds, equals the settled amount."],["Withholding","Where it applies it is a tax obligation, not a marketplace charge. The certificate is on the statement."],["Your margin","Settled less your cost. If commission and fees exceed your margin, the margin stack in the listing wizard says so before you publish rather than after."],["Querying a statement","Raise it from the statement itself so the query carries the reference. Settlement queries have their own resolution target."]]'::jsonb, 'published', 2),
('KB-P04', 'partner', 'howto', 'Make orders fulfil themselves', 4, '24 Jul 2026', 'pt-integrations', '{"PR-OWNER","PR-OPS"}', '{"api","fulfilment"}', 'Register an endpoint, subscribe to events, and check coverage.', '[["We call you","The marketplace calls your endpoint; you never poll us."],["Authentication","Unauthenticated endpoints are not accepted. Order payloads carry buyer data."],["Test before you rely on it","Send a test call from the console. A failing endpoint means orders are not acknowledged, and that shows on your listings."],["Coverage","A required event with no enabled endpoint is reported as unhandled. It is not queued and not retried later — it simply does not arrive."],["Retries","Delivery is retried with backoff. Persistent failure marks the endpoint unhealthy, which is visible to the catalogue team."]]'::jsonb, 'published', 3),
('KB-P05', 'partner', 'policy', 'Stock, reservations and overselling', 3, '23 Jul 2026', NULL, '{"PR-OWNER","PR-OPS"}', '{"inventory"}', 'Availability is on hand less reserved, and the storefront reads it.', '[["What a buyer sees","On hand less reserved. Not on hand. That is why a basket cannot promise stock the warehouse does not have."],["Reservations expire","A hold that is not converted releases back to the pool after its window, so an abandoned basket does not sterilise stock."],["Counts","A stock count below what is already reserved is refused, in the screen and in a bulk file. We cannot un-promise stock a customer has bought."],["Adjustments","Every movement is a record with a reason. A silent correction destroys the audit value of the ledger."]]'::jsonb, 'held', 4),
('KB-P06', 'partner', 'howto', 'Put your own branding on this console', 3, '25 Jul 2026', NULL, '{"PR-OWNER"}', '{"branding"}', 'Your livery here, and why it stops here.', '[["What you can change","Display name, logo with alt text, colours, light or dark, and which dashboard cards you see."],["Contrast is checked","A palette below WCAG AA cannot be applied. You are told which colour fails and by how much."],["Three cards cannot be hidden","Orders to fulfil, onboarding progress and open disputes. Hiding an obligation does not remove it."],["Where it stops","Your console is yours. Listings carry your name and logo inside the marketplace layout. The storefront, checkout and settlement documents stay in the marketplace’s livery — a checkout that restyles per seller erodes the trust buyers come for."]]'::jsonb, 'held', 5),
('KB-P07', 'partner', 'fix', 'My listing was rejected', 3, '24 Jul 2026', 'pt-listings', '{"PR-OWNER","PR-CAT"}', '{"catalogue","troubleshooting"}', 'Read the rule, fix the evidence, resubmit.', '[["Find the reason","Open the listing. The decision names the rule and what was missing."],["Common causes","Missing alt text; a sale price at or below cost; an expired certificate; a market you are not onboarded into."],["Resubmitting","Fix and resubmit — it re-enters the queue. Resubmitting unchanged will be rejected again with the same reason."],["If you disagree","Some rules are appealable and some are not; the decision says which. Where it is, raise a ticket citing the listing."]]'::jsonb, 'published', 6),
('KB-P08', 'partner', 'concept', 'Version history and rolling back a price', 3, '26 Jul 2026', 'pt-listings', '{"PR-OWNER","PR-CAT"}', '{"catalogue","pricing"}', 'Every published change is kept, and a rollback moves forward.', '[["Why it is kept","A pricing dispute is only resolvable from a record of what a buyer could have seen on a given date."],["Rollback","Reverting creates a new version carrying the earlier values. The intervening versions stay. History is never rewritten."],["What changed","The history shows the difference between consecutive versions field by field, not merely that something changed."]]'::jsonb, 'published', 7),
('KB-P09', 'partner', 'howto', 'Deciding a refund request', 4, '26 Jul 2026', NULL, '{"PR-OWNER","PR-FIN"}', '{"refunds","money","sla"}', 'You have 48 hours. Silence costs you the decision, not the money.', '[["Whose call it is","Yours, on anything you sold directly. The marketplace decides on its own products, on anything inside a bundle it assembled, and on anything you leave unanswered past the SLA."],["The clock","48 hours from the request. After that the marketplace answers on your behalf — and it is still recovered from your settlement. Not answering does not save you the money; it only costs you the say in it."],["A decline needs a reason","One sentence that a customer could read back to you. A decline without one gets escalated, and then somebody with less information than you decides it."],["Part refunds","Allowed, and they need the difference explained. \"Refunded three of twelve units, the other nine were delivered\" is a decision. A number with no explanation reads as arbitrary."],["What is never worth arguing","A duplicate charge and a non-delivery are auto-approved below the threshold precisely because arguing about them costs more than the refund."]]'::jsonb, 'held', 8),
('KB-P10', 'partner', 'concept', 'Credit and debit notes on your statement', 4, '26 Jul 2026', NULL, '{"PR-OWNER","PR-FIN"}', '{"settlement","money"}', 'An adjustment to a settlement already struck — and what to do if it is wrong.', '[["What a note is","A correction between the marketplace and you, after a settlement has been struck. A credit reduces what you owe us; a debit increases it. No customer is involved and no card is touched."],["When it applies","On your next statement. It does not move money on its own, which is why it has to be raised before the run closes."],["Disputing one","If it is wrong, dispute it rather than paying it. A disputed note does not settle while it is open, so it cannot be quietly deducted while the argument runs."],["Post it before the run","Put the note into your own ledger when it is issued, not when it settles. Reconciling a statement against books that have not seen the adjustment is where most settlement queries come from."]]'::jsonb, 'held', 9),
('KB-P11', 'partner', 'concept', 'Chasing your own customers', 5, '26 Jul 2026', NULL, '{"PR-OWNER","PR-FIN"}', '{"collections","dunning","money"}', 'You pace what you sold directly. The marketplace paces bundles, and what you owe it.', '[["You were given a ladder","At onboarding, chosen from the category you sell in. Run it as it stands, edit it, or add more — what recovers money from a games subscriber is not what recovers it from a fleet installer."],["Where yours does not apply","Anything sold inside a bundle the marketplace assembled runs on the marketplace ladder, whatever you have set. One customer, one bill, therefore one suspension date. Two ladders on one balance produce two dates and the customer believes whichever arrived first."],["What you owe us","Commission and fees run on the marketplace ladder. A debtor does not set the terms of their own recovery, and that includes you."],["The marketplace can see yours","Every ladder you publish is visible to us, with how far it has drifted from the default we gave you. That is not supervision for its own sake — when a customer complains about being chased, we have to be able to answer."],["A step that reaches nobody","If a channel is switched off, any step relying only on it is marked as not sending. A ladder can look complete and be doing nothing."]]'::jsonb, 'held', 10),
('KB-B01', 'enterprise', 'start', 'How buying here works', 3, '19 Jul 2026', 'en-dashboard', '{}', '{"overview"}', 'One catalogue, many sellers, one invoice and one set of approvals.', '[["One relationship","You contract with the marketplace, not with each seller. One invoice, one set of terms, one place to dispute."],["Approvals","Above your threshold a basket becomes a requisition. Who approves is set by policy, not per order."],["Contract pricing","Where your account has a negotiated price it applies automatically. Everyone else sees list."],["Your own branding","This portal carries your livery rather than the marketplace’s, because it is your people using it."]]'::jsonb, 'published', 0),
('KB-B02', 'enterprise', 'howto', 'Raise and track a requisition', 4, '21 Jul 2026', 'en-approvals', '{"BY-ADMIN","BY-BUY"}', '{"ordering","approvals"}', 'What triggers approval, who sees it, and what happens if nobody acts.', '[["What triggers it","Basket value above the threshold for your role, or any item in a controlled category."],["Who approves","Set in the approval policy — by value band, by cost centre, or both. A requisition can need more than one."],["If nobody acts","It escalates on the policy timer. It does not quietly expire, and the requester is told."],["Refusal","A refusal carries a reason. The basket is preserved so it can be amended and resubmitted rather than rebuilt."]]'::jsonb, 'published', 1),
('KB-B03', 'enterprise', 'concept', 'Contract pricing on your account', 3, '26 Jul 2026', NULL, '{"BY-ADMIN","BY-FIN"}', '{"pricing","commercial"}', 'Negotiated prices, minimum quantities and the unsigned rule.', '[["Scope","A contract price binds your account only. It does not leak to another buyer."],["Minimum quantity","Below the minimum, list price applies. That is the deal, not a fault."],["Unsigned prices","A negotiated price that is not signed is recorded and shown, but never charged. Recording the number before signature is useful; charging it is not."],["Expiry","A term that has ended stops applying without the record being deleted, so the history stays readable."]]'::jsonb, 'held', 2),
('KB-B04', 'enterprise', 'howto', 'Onboard a department at once', 3, '26 Jul 2026', NULL, '{"BY-ADMIN"}', '{"users","bulk"}', 'Load an HR extract instead of adding people one at a time.', '[["Template first","Download it pre-filled with your current users, edit the rows that change, and upload."],["Dry run","You see every change before anything is written. Bad rows are rejected individually with the reason."],["What it will not do","It updates existing users; it does not create or delete. And you cannot change your own role or status in a file."]]'::jsonb, 'held', 3),
('KB-B05', 'enterprise', 'concept', 'Invoices, cost centres and disputes', 4, '22 Jul 2026', 'en-profile', '{"BY-ADMIN","BY-FIN"}', '{"billing"}', 'One consolidated invoice, split the way your finance team needs it.', '[["Consolidation","Purchases across sellers arrive on one invoice on your cycle."],["Cost centres","Lines carry the cost centre of the requester, so the split does not have to be reconstructed later."],["Tax","Whether tax is included or added is stated, and shown once — never both ways on the same document."],["Disputing a line","Dispute the line rather than the invoice. It keeps the rest payable and the dispute specific."]]'::jsonb, 'published', 4),
('KB-B06', 'enterprise', 'fix', 'Something has not arrived', 3, '23 Jul 2026', 'en-orders', '{"BY-ADMIN","BY-BUY"}', '{"orders","troubleshooting"}', 'Where to look before raising a ticket, and what the ticket needs.', '[["Check the pipeline","Open the order. Each fulfilment type has its own stages, and the stalled one is named."],["Physical items","Carrier and tracking are on the order. A carrier exception is shown as an exception, not as a shipment that is quietly late."],["Digital and provisioned items","A failed activation shows the reason from the seller’s system rather than a generic failure."],["Raising it","Raise from the order so the ticket carries the reference. Priority is set by impact, not by who is asking."]]'::jsonb, 'published', 5),
('KB-C01', 'consumer', 'start', 'Getting started', 2, '20 Jul 2026', 'home', '{}', '{"overview"}', 'What you can buy here and how it reaches you.', '[["One place","Plans, handsets, insurance, security and content, from the operator and from partners, on one account and one bill."],["How things arrive","A handset ships. A plan or an eSIM activates. Content and security are switched on. The order tells you which and how far along it is."],["Paying","Card, wallet or on your operator bill where that is available to you."]]'::jsonb, 'published', 0),
('KB-C02', 'consumer', 'howto', 'Compare before you buy', 2, '26 Jul 2026', 'category', '{}', '{"shopping"}', 'Up to three side by side, on the things that differ.', '[["How","Tick compare on a product card. The tray keeps your picks while you keep browsing."],["Three at a time","A table wide enough to need scrolling stops being a comparison."],["What the highlight means","It marks the best value in that row only. It is arithmetic on one dimension, not a recommendation — the dimension that matters is yours to choose."]]'::jsonb, 'published', 1),
('KB-C03', 'consumer', 'howto', 'Manage a subscription', 2, '24 Jul 2026', 'subscriptions', '{}', '{"subscriptions"}', 'Pause, cancel, restart, or turn auto-renew off across several at once.', '[["Pause versus cancel","Pausing keeps your settings and your place. Cancelling ends it at the end of the paid period — you keep what you have paid for."],["Auto-renew","Turning it off is reversible and does not cancel anything. You can change it on several subscriptions at once."],["What it will cost","The projection on this screen is a forecast of your current commitments, not a bill."]]'::jsonb, 'published', 2),
('KB-C04', 'consumer', 'fix', 'A payment failed', 2, '26 Jul 2026', 'account', '{}', '{"billing","troubleshooting"}', 'What happens next, and how long you have.', '[["You are told","A failure appears on your account with the amount, the date and the reason."],["Nothing stops immediately","Service continues while we retry. Nothing is suspended before day fourteen."],["Expired cards","A retry against an expired card cannot succeed. Update the card rather than waiting for another attempt."],["If you need time","A promise to pay pauses the reminders until the date you choose."]]'::jsonb, 'published', 3),
('KB-C05', 'consumer', 'howto', 'Write a review', 2, '25 Jul 2026', 'orders', '{}', '{"reviews"}', 'Who can review, what is checked, and how long it takes.', '[["Who","Only someone who bought the item on this account."],["Moderation","Reviews are checked for content, not for sentiment. A negative review is not a reason to reject one, and every rejection reason is recorded against the moderator."],["Timing","A pending review does not move the rating — otherwise moderation would be pointless."],["Seller replies","A seller may respond publicly. They cannot edit or remove your review."]]'::jsonb, 'published', 4),
('KB-C06', 'consumer', 'policy', 'Who else can get into this account', 2, '26 Jul 2026', 'account', '{}', '{"security"}', 'Devices, sessions and what to do if one looks wrong.', '[["Your devices","Every device signed in is listed with where and when. An unusual location is flagged."],["Ending one","Ending a session signs that device out immediately. It does not change your password — if the password is what leaked, change that too."],["Sharing","People you add to the account can be given a spend cap. What each may do is on the account access screen."]]'::jsonb, 'published', 5)
ON CONFLICT (id) DO NOTHING;

INSERT INTO kb_tours (id, persona, title, mins, why, stops, status, sort_order) VALUES
('TR-O1', 'operator', 'Take a seller from application to first sale', 6, 'The path most new operators are asked to walk on day one.', '[{"view":"op-onboarding","at":"Partner onboarding","say":"Seven gates. The funnel shows where applications actually stall, which is almost never where people assume."},{"view":"op-onboarding","at":"A single application","say":"Open one. Every gate keeps what the seller submitted, so a decision can be re-read months later."},{"view":null,"at":"Listing rules","say":"What every listing is checked against. Set the level per category in the matrix."},{"view":"op-catalogue","at":"Catalogue queue","say":"Their first listing lands here. Approving it publishes; rejecting it returns a reason the seller can act on."},{"view":null,"at":"Commission plans","say":"What the marketplace earns on that sale, and under which commercial model."},{"view":"op-settlement","at":"Settlement runs","say":"And what the seller is paid, less commission, fees, withholding and refunds."}]'::jsonb, 'held', 0),
('TR-O2', 'operator', 'Understand where the money goes', 5, 'Gross value is not revenue, and settlement is not profit. This is the chain between them.', '[{"view":"op-dashboard","at":"Marketplace overview","say":"Gross value across every category. The projection states its method and how wrong it was last quarter."},{"view":null,"at":"Commission plans","say":"Seven commercial models. Changing the model changes which parameters even apply."},{"view":"op-promotions","at":"Promotions","say":"Discount rules, and the floor no rule may cross. The engine clamps at cost, not the rule author."},{"view":null,"at":"Tax configuration","say":"Who is merchant of record decides who owes the tax. That is a commercial decision before it is a tax one."},{"view":"op-settlement","at":"Settlement runs","say":"The statement reconciles to order lines. Approving it is the point of no return, so it asks twice."},{"view":"op-dunning","at":"Collections","say":"And when a payment fails, the ladder that recovers it without manufacturing churn."}]'::jsonb, 'held', 1),
('TR-O3', 'operator', 'Prove the platform is governable', 4, 'The questions an auditor or a security reviewer will ask, and where each is answered.', '[{"view":null,"at":"Users","say":"Who has access, with what role, and whether their second factor is on."},{"view":"op-roles","at":"Roles configuration","say":"What each role may do, as a grid rather than as prose."},{"view":"op-audit","at":"Audit log","say":"Append-only, hash-chained, streamed to a SIEM outside the control of the people it audits."},{"view":null,"at":"Bulk updates","say":"Mass change with a mandatory dry run, per-row rejection, and one audit entry per job."}]'::jsonb, 'held', 2),
('TR-P1', 'partner', 'Get your first listing live', 5, 'From an approved account to a published SKU.', '[{"view":"pt-onboarding","at":"Onboarding","say":"Clear every gate first. A listing cannot publish while a gate is open."},{"view":"pt-newlisting","at":"New listing","say":"Six steps. Media and alt text are required before submission, not after."},{"view":"pt-newlisting","at":"Pricing and commission","say":"Cost, list and sale are three separate numbers. The margin stack shows what is left after everyone takes their cut."},{"view":"pt-integrations","at":"Integrations","say":"Point fulfilment at an endpoint, or orders wait for someone to open the portal."},{"view":"pt-listings","at":"My listings","say":"It appears here once submitted, and moves to live when the catalogue team clears it."}]'::jsonb, 'held', 0),
('TR-P2', 'partner', 'Understand what you actually get paid', 4, 'The gap between a sale price and a bank credit, itemised.', '[{"view":"pt-plan","at":"Settlement plan","say":"Your commercial model and the rate that applies to each category."},{"view":"pt-settlement","at":"Settlement","say":"The statement reconciles to your orders. Every deduction is named."},{"view":"pt-dashboard","at":"Dashboard","say":"The settlement projection is a forecast with a stated method, not a payment schedule."},{"view":null,"at":"Support tickets","say":"If a statement looks wrong, raise it here. Settlement queries have their own SLA."}]'::jsonb, 'held', 1),
('TR-B1', 'enterprise', 'Buy something that needs approval', 4, 'The requisition path, end to end, including what happens when it is refused.', '[{"view":"en-browse","at":"Catalogue","say":"Contract prices apply automatically where your account has one."},{"view":"en-browse","at":"Basket","say":"Above your threshold this becomes a requisition rather than an order."},{"view":"en-approvals","at":"Approvals","say":"Who approves, in what order, and what happens if they do not."},{"view":"en-orders","at":"Orders","say":"Approved requisitions become orders here, with their fulfilment state."}]'::jsonb, 'held', 0),
('TR-B2', 'enterprise', 'Set the account up for a department', 4, 'Users, what they may spend, and who signs it off.', '[{"view":null,"at":"Users","say":"Add people, or load a department at once from an HR extract."},{"view":null,"at":"Roles configuration","say":"What each role may buy and approve."},{"view":null,"at":"Bulk updates","say":"A joiners file changes many users at once, with a dry run first."},{"view":null,"at":"Contract pricing","say":"Negotiated prices for this account, and the rule that an unsigned one is recorded but never charged."}]'::jsonb, 'held', 1),
('TR-C1', 'consumer', 'Find something and buy it', 3, 'The shortest path through the storefront.', '[{"view":"category","at":"Browse","say":"Compare up to three side by side. Availability is read from real stock, not a label."},{"view":"category","at":"Basket","say":"Tax is shown as included or added, never both. Promotions state what applied and what did not."},{"view":"orders","at":"Orders","say":"Track it here. A physical item shows carrier and tracking."}]'::jsonb, 'held', 0),
('TR-C2', 'consumer', 'Look after your account', 3, 'Subscriptions, payments and who else can get in.', '[{"view":"subscriptions","at":"Subscriptions","say":"Pause, cancel or restart. Auto-renew can be changed for several at once."},{"view":"account","at":"My details","say":"If a payment fails you are told here, and told plainly what has and has not stopped."},{"view":"account","at":"Sign-in and devices","say":"Every device signed in to this account, and how to end one you do not recognise."}]'::jsonb, 'held', 1)
ON CONFLICT (id) DO NOTHING;
